144→// ReadTemporary reads the latest checkpoint from a shadow branch.
145→// Returns nil if the shadow branch doesn't exist.
146→// worktreeID should be empty for main worktree or the internal git worktree name for linked worktrees.
147→func (s *GitStore) ReadTemporary(ctx context.Context, baseCommit, worktreeID string) (*ReadTemporaryResult, error) {
148→	if err := ctx.Err(); err != nil {
149→		return nil, err //nolint:wrapcheck // Propagating context cancellation
150→	}
151→
152→	shadowBranchName := ShadowBranchNameForCommit(baseCommit, worktreeID)
153→	refName := plumbing.NewBranchReferenceName(shadowBranchName)
154→
155→	ref, err := s.repo.Reference(refName, true)
156→	if err != nil {
157→		return nil, nil //nolint:nilnil,nilerr // Branch not found is an expected case
158→	}
159→
160→	commit, err := s.repo.CommitObject(ref.Hash())
161→	if err != nil {
162→		return nil, fmt.Errorf("failed to get commit object: %w", err)
163→	}
164→
165→	// Extract session ID and metadata dir from commit trailers
166→	sessionID, _ := trailers.ParseSession(commit.Message)
167→	metadataDir, _ := trailers.ParseMetadata(commit.Message)
168→
169→	return &ReadTemporaryResult{
170→		CommitHash:  ref.Hash(),
171→		TreeHash:    commit.TreeHash,
172→		SessionID:   sessionID,
173→		MetadataDir: metadataDir,
174→		Timestamp:   commit.Author.When,
175→	}, nil
176→}
