765→// createCommit creates a commit object.
766→func (s *GitStore) createCommit(treeHash, parentHash plumbing.Hash, message, authorName, authorEmail string) (plumbing.Hash, error) {
767→	now := time.Now()
768→	sig := object.Signature{
769→		Name:  authorName,
770→		Email: authorEmail,
771→		When:  now,
772→	}
773→
774→	commit := &object.Commit{
775→		TreeHash:  treeHash,
776→		Author:    sig,
777→		Committer: sig,
778→		Message:   message,
779→	}
780→
781→	// Add parent if not a new branch
782→	if parentHash != plumbing.ZeroHash {
783→		commit.ParentHashes = []plumbing.Hash{parentHash}
784→	}
785→
786→	obj := s.repo.Storer.NewEncodedObject()
787→	if err := commit.Encode(obj); err != nil {
788→		return plumbing.ZeroHash, fmt.Errorf("failed to encode commit: %w", err)
789→	}
